julia-3d.src:
#version 300 es
precision highp float;
out vec4 o;
uniform vec2 r;
uniform float t;
uniform vec3 eye, target;
uniform float u_juliaRe;    // @slider -1.0 1.0 -0.7269
uniform float u_juliaIm;    // @slider -1.0 1.0 0.1889
uniform float u_juliaCc;    // @slider -0.5 0.5 0.0

float g_it = 0.0;

// Quaternion square: (a+bi+cj+dk)^2
void qsq(inout float a, inout float b, inout float c, inout float d) {
    float a2 = a*a - b*b - c*c - d*d;
    float b2 = 2.0*a*b;
    float c2 = 2.0*a*c;
    float d2 = 2.0*a*d;
    a = a2; b = b2; c = c2; d = d2;
}

// Quaternion Julia distance estimator
float juliaDE(vec3 p) {
    // 3D slice of 4D quaternion space (d=0)
    float a = p.x, b = p.y, c = p.z, d = 0.0;

    // Julia constant (user-controlled via uniforms instead of animated)
    float ca = u_juliaRe;
    float cb = u_juliaIm;
    float cc = u_juliaCc;
    float cd = 0.0;

    // Derivative for distance estimation
    float da = 1.0, db = 0.0, dc = 0.0, dd = 0.0;
    float m = 0.0;
    g_it = 0.0;

    for (int i = 0; i < 64; i++) {
        // dz' = 2 * z * dz (quaternion derivative)
        float tda = 2.0*(a*da - b*db - c*dc - d*dd);
        float tdb = 2.0*(a*db + b*da + c*dd - d*dc);
        float tdc = 2.0*(a*dc - b*dd + c*da + d*db);
        float tdd = 2.0*(a*dd + b*dc - c*db + d*da);
        da = tda; db = tdb; dc = tdc; dd = tdd;

        // z' = z^2 + c
        qsq(a, b, c, d);
        a += ca; b += cb; c += cc; d += cd;

        m = a*a + b*b + c*c + d*d;
        if (m > 4.0) break;
        g_it = float(i);
    }

    // Distance estimation: 0.5 * |z| * log(|z|) / |dz|
    float zmag = sqrt(m);
    float dzmag = sqrt(da*da + db*db + dc*dc + dd*dd);
    return 0.5 * zmag * log(max(zmag, 1.0001)) / max(dzmag, 0.0001);
}

float scene(vec3 p) {
    return juliaDE(p);
}

vec3 norm(vec3 p) {
    vec2 e = vec2(0.001, 0.0);
    return normalize(vec3(
        scene(p+e.xyy)-scene(p-e.xyy),
        scene(p+e.yxy)-scene(p-e.yxy),
        scene(p+e.yyx)-scene(p-e.yyx)
    ));
}

vec3 shade(vec3 p, vec3 n, vec3 rd, float it) {
    // Iteration-based coloring (matching 2D Julia's cosine palette)
    float f = it / 64.0;
    vec3 col = 0.5 + 0.5*cos(vec3(0.5, 1.0, 2.0)*f*8.0 + t*0.05);
    col = mix(col, vec3(0.0), smoothstep(0.85, 1.0, f));

    // Subtle orbit-trap position color
    vec3 posCol = 0.5 + 0.5*cos(vec3(1.0, 2.0, 3.0)*length(p)*0.8 + t*0.1);
    col = mix(col, posCol, 0.15);

    // 3D lighting
    vec3 L = normalize(vec3(5, 8, 6));
    float amb = 0.15;
    float dif = max(dot(n, L), 0.0);
    float bac = max(dot(n, normalize(vec3(-3, 4, -5))), 0.0)*0.3;
    float occ = 0.5 + 0.5*scene(p+n*0.15);
    float spec = pow(max(dot(reflect(-L, n), -rd), 0.0), 32.0);

    col *= (amb + dif*0.7 + bac + occ*0.6);
    col += vec3(1.0, 0.8, 0.5)*spec*0.6;

    // Rim light for filamentary tendrils
    float rim = pow(1.0 - max(dot(-rd, n), 0.0), 3.0);
    col += vec3(0.3, 0.2, 0.6)*rim*0.4;

    return col;
}

void main() {
    vec2 uv = (gl_FragCoord.xy - 0.5*r) / r.y;
    vec3 fwd = normalize(target - eye);
    vec3 right = normalize(cross(fwd, vec3(0, 1, 0)));
    vec3 up = cross(right, fwd);
    vec3 rd = normalize(uv.x*right + uv.y*up + fwd*1.8);

    float th = 0.0, d;
    vec3 p;
    for (int i = 0; i < 60; i++) {
        p = eye + rd*th;
        d = scene(p);
        if (d < 0.001 || th > 30.0) break;
        th += d * 0.7;
    }

    vec3 col;
    if (th < 30.0 && d < 0.001) {
        float hitIt = g_it;
        vec3 n = norm(p);
        col = shade(p, n, rd, hitIt);
    } else {
        col = vec3(0.02, 0.02, 0.05);
    }

    float vig = 1.0 - 0.3*length(uv);
    col *= vig;
    o = vec4(col, 1);
}

