#version 300 es
precision highp float;
out vec4 o;
uniform vec2 r;
uniform float t;
uniform vec3 eye, target;

// Rotation matrix generator
mat2 rot(float a) {
    float c = cos(a), s = sin(a);
    return mat2(c, -s, s, c);
}

// Infinite Mandelbox-style space folding and twisting DE
float scene(vec3 p) {
    float flow = t * 0.2;
    p.xy *= rot(p.z * 0.1 + flow);
    p.xz *= rot(sin(flow * 0.5) * 0.5);

    vec3 z = p;
    float scale = -1.8;
    float dr = 1.0;

    for (int i = 0; i < 7; i++) {
        z = clamp(z, -1.0, 1.0) * 2.0 - z;

        float m = dot(z, z);
        if (m < 0.25) {
            float inv = 4.0;
            z *= inv;
            dr *= inv;
        } else if (m < 1.0) {
            float inv = 1.0 / m;
            z *= inv;
            dr *= inv;
        }

        z = z * scale + p + vec3(sin(t*0.1)*0.2, cos(t*0.15)*0.2, 0.0);
        dr = dr * abs(scale) + 1.0;
    }

    return length(z) / abs(dr);
}

vec3 norm(vec3 p) {
    vec2 e = vec2(0.002, 0.0);
    return normalize(vec3(
        scene(p+e.xyy) - scene(p-e.xyy),
        scene(p+e.yxy) - scene(p-e.yxy),
        scene(p+e.yyx) - scene(p-e.yyx)
    ));
}

void main() {
    vec2 uv = (gl_FragCoord.xy - 0.5 * r) / r.y;

    vec3 ro = vec3(0.0, 0.0, -3.5 + sin(t*0.2)*1.0);
    vec3 rd = normalize(vec3(uv, 1.0 - dot(uv, uv)*0.2));

    float th = 0.0, d = 0.0;
    vec3 p = ro;
    float glow = 0.0;

    for (int i = 0; i < 90; i++) {
        p = ro + rd * th;
        d = scene(p);
        glow += exp(-3.0 * abs(d));
        if (d < 0.001 || th > 20.0) break;
        th += d * 0.5;
    }

    vec3 col = vec3(0.0);

    if (d < 0.001) {
        vec3 n = norm(p);
        vec3 light = normalize(vec3(cos(t), 2.0, sin(t)));
        float diff = max(dot(n, light), 0.0);
        float fresnel = pow(1.0 - max(dot(-rd, n), 0.0), 4.0);
        vec3 baseCol = 0.5 + 0.5 * cos(vec3(3.0, 2.0, 1.0) * length(p) * 0.4 + t * 0.5);
        col = baseCol * diff + vec3(0.1, 0.4, 0.8) * fresnel;
    } else {
        col = vec3(0.02, 0.01, 0.05) * length(uv);
    }

    col += glow * vec3(0.1, 0.03, 0.2) * (0.5 + 0.5 * sin(t));
    col *= 1.0 - 0.4 * length(uv);
    col = pow(col, vec3(0.4545));

    o = vec4(col, 1.0);
}

