#version 300 es
precision highp float;
out vec4 o;
uniform vec2 r;
uniform float t;
uniform vec3 eye, target;

// === 5D Hyper-Shadow Controls ===
uniform float u_w;           // @slider -2.5 2.5 0.0  4th dim (w)
uniform float u_v;           // @slider -2.5 2.5 0.0  5th dim (v)
uniform float u_lightW;      // @slider -4.0 4.0 2.0  Light depth (wℓ)
uniform float u_rippleFreq;  // @intslider 1 6 3     5D ripple bands
uniform float u_shadowDark;  // @slider 0.0 1.0 0.7  Shadow darkness

// ---- 5D Hyper-Torus Distance Estimator ----
// F(x,y,z,w,v) = distance to a 5D deformed torus
// Sliders u_w, u_v pick a 3D slice through the 5D surface
float de5D(vec3 p, float w, float v) {
    // Torus radii undulate with the extra dimensions
    float R = 1.8 + 0.3 * sin(w * 1.3) * cos(v * 0.7);
    float r = 0.55 + 0.2 * sin(v * 1.1 + w * 0.5);

    // 3D torus at this 5D slice
    vec2 q = vec2(length(p.xz) - R, p.y);
    float d = length(q) - r;

    // 5D ripples: the surface undulates in all 5 dimensions
    float f = floor(u_rippleFreq + 0.5);
    d += 0.035 * sin(p.x*f + w*1.2) * cos(p.y*f*0.9 + v*0.8) * sin(p.z*f*1.1 + w*0.5 + t*0.15);
    d += 0.020 * sin((p.x+p.z)*f*0.7 + w*1.5 + v*1.1 + t*0.1);
    d += 0.012 * cos(p.x*f*1.4 - p.y*f*0.8 + p.z*f*1.2 + w*0.9 + v*1.3);
    return d;
}

float scene(vec3 p) { return de5D(p, u_w, u_v); }

// ---- 4D Gradient (surface normal in x,y,z,w space) ----
vec4 grad4D(vec3 p, float w, float v) {
    float eps = 0.001;
    float f = de5D(p, w, v);
    return vec4(
        de5D(p+vec3(eps,0,0), w, v) - f,
        de5D(p+vec3(0,eps,0), w, v) - f,
        de5D(p+vec3(0,0,eps), w, v) - f,
        de5D(p, w+eps, v) - f
    ) / eps;
}

vec3 norm(vec3 p) {
    vec2 e = vec2(0.001, 0.0);
    return normalize(vec3(
        de5D(p+e.xyy, u_w, u_v) - de5D(p-e.xyy, u_w, u_v),
        de5D(p+e.yxy, u_w, u_v) - de5D(p-e.yxy, u_w, u_v),
        de5D(p+e.yyx, u_w, u_v) - de5D(p-e.yyx, u_w, u_v)
    ));
}

// ---- 3D Shadow via 5D Occlusion ----
// Traces toward light in 3D, but the 4th dimension (w)
// interpolates along the ray. If de5D < 0 at any interpolated
// 5D position, the surface blocks the 4D light → a 3D shadow.
float shadow4D(vec3 p, vec3 lightDir, float lightDist) {
    float res = 1.0;
    float t = 0.02;
    float w0 = u_w, lw = u_lightW;
    for (int i = 0; i < 40; i++) {
        vec3 q = p + lightDir * t;
        float wq = w0 + (lw - w0) * (t / lightDist);
        float d = de5D(q, wq, u_v);
        if (d < 0.001) return 0.0;
        res = min(res, 12.0 * d / t);
        t = min(t + max(d * 0.5, 0.01), lightDist * 0.99);
    }
    return res;
}

void main() {
    vec2 uv = (gl_FragCoord.xy - 0.5*r) / r.y;
    vec3 fwd = normalize(target - eye);
    vec3 rgt = normalize(cross(fwd, vec3(0,1,0)));
    vec3 up  = cross(rgt, fwd);
    vec3 rd  = normalize(uv.x*rgt + uv.y*up + fwd*1.8);

    // ---- Raymarch ----
    float th = 0.0, d;
    vec3 p;
    bool hit = false;
    for (int i = 0; i < 80; i++) {
        p = eye + rd * th;
        d = scene(p);
        if (d < 0.001) { hit = true; break; }
        if (th > 30.0) break;
        th += d * 0.7;
    }

    vec3 col;
    if (hit) {
        // 5D surface hit → compute 4D gradient & normals
        vec4 g  = grad4D(p, u_w, u_v);
        vec3 n3 = normalize(g.xyz);       // 3D normal (fresnel, amb occ)
        vec4 n4 = normalize(g);           // 4D normal (light diffuse)

        // 4D light: 3D position + extra-dimensional depth
        vec3 lightPos = vec3(3.0, 5.0, 4.0);
        vec3 L3 = lightPos - p;
        float lDist = length(L3);
        vec3 lDir = L3 / lDist;
        vec4 L4 = normalize(vec4(L3, u_lightW - u_w));

        // 4D diffuse — depends on 4D normal alignment with 4D light
        float dif = max(dot(n4, L4), 0.0);

        // 3D shadow — computed via 5D occlusion
        float shadow = 1.0;
        if (dif > 0.01 && u_shadowDark > 0.01) {
            shadow = shadow4D(p, lDir, lDist);
            shadow = mix(1.0, shadow, u_shadowDark);
        }

        // Ambient & Fresnel
        float amb    = 0.15 + 0.08 * max(n3.y, 0.0);
        float fresnel = pow(1.0 - max(dot(-rd, n3), 0.0), 3.0);

        // Iridescent colour: hue shifts with 4D normal orientation
        float hue = n4.x*0.15 + n4.y*0.3 + atan(n4.w, n4.z)*0.4;
        vec3 baseCol = 0.5 + 0.5*cos(vec3(0.0, 2.1, 4.2) + hue);

        // Composite
        col = baseCol * (dif * shadow + amb);
        col += vec3(0.3, 0.5, 1.0) * fresnel * 0.5;   // dimensional rim glow
        col += baseCol * 0.04 * exp(-abs(u_w) * 0.3);  // 4D subsurface

        // Warm shadow tint — the "redshift" of light escaping extra dimensions
        col *= 1.0 + vec3(0.3, 0.15, 0.05) * (1.0 - shadow) * 0.5;
    } else {
        // Deep-space background
        col = mix(vec3(0.02, 0.01, 0.06), vec3(0.06, 0.08, 0.18), abs(rd.y));
        float stars = pow(max(0.0, fract(
            sin(dot(rd*100.0, vec3(12.99,78.23,45.16)))*43758.55
        )-0.985), 8.0);
        col += vec3(0.8, 0.9, 1.0) * stars;
    }

    col *= 1.0 - 0.2 * length(uv);  // vignette
    col = col / (col + 1.0);         // Reinhard tonemap
    o = vec4(clamp(col, 0.0, 1.0), 1.0);
}
